import { WindowConf } from "@droid/android";
import { Log, useTranslation } from "@fanfanlo";
import { Card, CardContent, Typography, Box, CardActions, Button, Stack, Switch } from "@mui/material";
import { useEffect, useState } from "react";
import { androidFloatWindowData } from "./data";
import { autoWebViewJs } from "@droid/android";
import { openFloatWindow } from "./android-window";

const fileLog = new Log(false, 'WindowConfPreview_tsx');
// WindowConfPreview - 用于列表中的快速预览
export function WindowConfPreview({
  windowConf,
  onEdit,
  onDelete
}: {
  windowConf: WindowConf;
  onEdit: () => void;
  onDelete: () => void;
}) {
    const uiLog = fileLog.sub(false, 'WindowConfPreview_fn');
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [isOpen, setIsOpen] = useState(false);

  const refreshIsOpen = () => {
    const fnLog = uiLog.sub(false, 'refreshIsOpen_fn')
    const script = `
    var isOpen = com.fanfanlo.lib.components.floatview.floatwindow.Window.isShow("${androidFloatWindowData.getItemId(windowConf)}");
    isOpen;`;
    const { javaResultString, errMsg } = autoWebViewJs.callScript<boolean>(script);
    fnLog.log('refreshIsOpen sript=', script, `errMsg=${errMsg} and result string = ${javaResultString}`);
    if (errMsg) {
      fnLog.log('refresh is open err', errMsg);
      return;
    }
    setIsOpen(javaResultString === 'true');
  };
  useEffect(() => {
    const effLog = uiLog.sub(false, 'effect_fn')
    refreshIsOpen();
    const dismissType = androidFloatWindowData.getDismissEventType(windowConf);
    const openedType = androidFloatWindowData.getOpenedEventType(windowConf);
    effLog.log('dismissType =', dismissType);
    effLog.log('openedType=', openedType);
    window.addEventListener(dismissType as any, onDismiss);
    window.addEventListener(openedType as any, onOpened);
    function onDismiss() {
      effLog.log('dismiss')
      setIsOpen(false);
    }
    function onOpened(){
      effLog.log('opened')
      setIsOpen(true)
    }
    return () => {
      effLog.log('remove eventlistener')
      window.removeEventListener(dismissType as any, onDismiss);
      window.removeEventListener(openedType as any, onOpened);
    };
  }, []);
  const handleToggle = (checked: boolean) => {
    console.log('WindowConfPreview: handleToggle - checked=', checked);
    // setIsOpen(checked);

    if (checked) {
      // TODO: 改造 openFloatWindow 方法后再执行
      console.log('WindowConfPreview: handleToggle - would open window with windowId:', windowConf.windowId);
      openFloatWindow(windowConf);
    } else {
      const script = `
      com.fanfanlo.lib.components.floatview.floatwindow.Window.exitById("${windowConf.windowId}")`;
      console.log('WindowConfPreview: handleToggle - script=', script);
      autoWebViewJs.callScript(script);
    }
  };

  return (
    <Card sx={{ mb: 2 }}>
      <CardContent>
        {/* 标题 + 开关 */}
        <Stack direction="row" spacing={2} alignItems="center" sx={{ mb: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 'bold', flex: 1 }}>
            {windowConf.tag}
          </Typography>
          <Switch
            checked={isOpen}
            onChange={e => handleToggle(e.target.checked)}
            title={isOpen ? t('WindowConfPreview.stopRunning') : t('WindowConfPreview.startRunning')}
          />
        </Stack>

        {/* 说明区域 */}
        {windowConf.description && (
          <Typography
            variant="body2"
            sx={{
              mb: 2,
              p: 1.5,
              bgcolor: 'background.secondary',
              borderRadius: 1,
              borderLeft: '3px solid',
              borderLeftColor: 'primary.main'
            }}
          >
            {windowConf.description}
          </Typography>
        )}

        {!windowConf.description && (
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ mb: 2, fontStyle: 'italic' }}
          >
            {t('WindowConfPreview.noDescription')}
          </Typography>
        )}
      </CardContent>

      <CardActions sx={{ justifyContent: 'flex-end', gap: 1 }}>
        <Button size="small" onClick={onEdit} variant="outlined">
          {t('WindowConfPreview.detailEdit')}
        </Button>
        <Button size="small" onClick={onDelete} color="error" variant="outlined">
          {t('WindowConfPreview.delete')}
        </Button>
      </CardActions>
    </Card>
  );
}
